interface Context<Env = any, Path extends string = any> {
  env: Env;
  path: Path;
}

function matchesAny(...conditions: ((c: Context) => boolean)[]) {
  return (c: Context) => conditions.some((cond) => cond(c));
}

matchesAny((c: Context) => c.path === "/")({ env: {}, path: "/" });

